import{_ as i,C as n,o as t,c as r,a2 as s,b as h,w as a,a as l,E as d,a3 as p}from"./chunks/framework.Ci_RTJJ5.js";const E=JSON.parse('{"title":"06 — Overview","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/06-sessions/overview.md","filePath":"chapters/06-sessions/overview.md"}'),c={name:"chapters/06-sessions/overview.md"};function u(g,e,k,m,y,b){const o=n("Mermaid");return t(),r("div",null,[e[1]||(e[1]=s(`<h1 id="_06-—-overview" tabindex="-1">06 — Overview <a class="header-anchor" href="#_06-—-overview" aria-label="Permalink to &quot;06 — Overview&quot;">​</a></h1><p><em>How sessions work, and what belongs in one. Read this before you write code.</em></p><hr><h2 id="a-session-is-a-log-not-a-snapshot" tabindex="-1">A session is a log, not a snapshot <a class="header-anchor" href="#a-session-is-a-log-not-a-snapshot" aria-label="Permalink to &quot;A session is a log, not a snapshot&quot;">​</a></h2><p>There are two ways to persist a conversation. You can save the current state, or you can save every change that produced it.</p><p>Snapshots are smaller and easier to read. Logs win on two properties that matter here:</p><table tabindex="0"><thead><tr><th>Property</th><th>Snapshot</th><th>Append-only log</th></tr></thead><tbody><tr><td>A crash mid-write</td><td>the file is half-written and useless</td><td>the last line is lost, the rest is fine</td></tr><tr><td>Two readers</td><td>must agree on a lock</td><td>both read the same prefix</td></tr><tr><td>History of how you got here</td><td>lost</td><td>kept</td></tr></tbody></table><p>So the format is one JSON object per line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;type&quot;:&quot;header&quot;,&quot;version&quot;:1,&quot;created&quot;:&quot;2026-10-27T10:00:00Z&quot;}</span></span>
<span class="line"><span>{&quot;type&quot;:&quot;message&quot;,&quot;message&quot;:{&quot;role&quot;:&quot;user&quot;,&quot;content&quot;:&quot;which branch?&quot;}}</span></span>
<span class="line"><span>{&quot;type&quot;:&quot;message&quot;,&quot;message&quot;:{&quot;role&quot;:&quot;assistant&quot;,&quot;content&quot;:&quot;release&quot;}}</span></span></code></pre></div><p>JSONL also means <code>tail -f work.jsonl</code> is a debugging tool, and <code>jq</code> is the query language. Neither needs your program.</p><h2 id="store-the-conversation-rebuild-the-policy" tabindex="-1">Store the conversation. Rebuild the policy. <a class="header-anchor" href="#store-the-conversation-rebuild-the-policy" aria-label="Permalink to &quot;Store the conversation. Rebuild the policy.&quot;">​</a></h2><p>The session holds user, assistant and tool messages. It does <strong>not</strong> hold the system message.</p>`,12)),(t(),h(p,null,{default:a(()=>[d(o,{id:"mermaid-79",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20S%5B%22session%20file%3Cbr%2F%3Euser%2C%20assistant%2C%20tool%22%5D%20--%3E%20L%5B%22Load%22%5D%0A%20%20%20%20A%5B%22AGENTS.md%3Cbr%2F%3Ecurrent%20contents%22%5D%20--%3E%20B%5B%22BuildSystemPrompt%22%5D%0A%20%20%20%20P%5B%22new%20prompt%22%5D%20--%3E%20H%0A%20%20%20%20L%20--%3E%20H%5B%22history%22%5D%0A%20%20%20%20B%20--%3E%20H%0A%20%20%20%20H%20--%3E%20R%5B%22RunLoop%22%5D%0A%20%20%20%20R%20--%3E%7C%22new%20messages%20only%22%7C%20S%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s(`<p>Two reasons the system message stays out:</p><ol><li><strong>It is policy for this run.</strong> If <code>AGENTS.md</code> changed since yesterday, the agent should follow the new rules, not replay the old ones.</li><li><strong>It must appear once.</strong> A program that both stores it and rebuilds it sends two on resume, and the second contradicts the first.</li></ol><p>The rule generalises: <strong>store facts, rebuild decisions.</strong></p><h2 id="resume-is-a-slice-and-the-slice-is-where-the-bug-is" tabindex="-1">Resume is a slice, and the slice is where the bug is <a class="header-anchor" href="#resume-is-a-slice-and-the-slice-is-where-the-bug-is" aria-label="Permalink to &quot;Resume is a slice, and the slice is where the bug is&quot;">​</a></h2><p>The obvious implementation loads the history, appends it to the new request, and then records &quot;everything&quot; afterwards. That records the loaded history a second time:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  turn 1:  file = [u1, a1]</span></span>
<span class="line"><span>  resume:  history = [system, u1, a1, u2]</span></span>
<span class="line"><span>  save:    history[1:] = [u1, a1, u2]      ← u1 and a1 written again</span></span>
<span class="line"><span>  file =   [u1, a1, u1, a1, u2]</span></span></code></pre></div><p>The next run sends <code>u1, a1, u1, a1, u2</code>, so the model sees the conversation twice, the context fills twice as fast, and nothing looks obviously wrong.</p><p>The fix is one number. Remember how many messages were loaded, and save only what comes after them:</p><div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">prior </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rec.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Load</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">history </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> append</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">([]</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{Role: RoleSystem, Content: system}}, prior</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">history </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> append</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(history, userMessage)</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ...</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> _, m </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> range</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> res.History[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">len</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(prior)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:] {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	rec.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Append</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(m)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>len(prior)+1</code> skips the system message and the loaded history in one expression. That <code>+1</code> is the chapter.</p><h2 id="tool-pairs-cross-run-boundaries-too" tabindex="-1">Tool pairs cross run boundaries too <a class="header-anchor" href="#tool-pairs-cross-run-boundaries-too" aria-label="Permalink to &quot;Tool pairs cross run boundaries too&quot;">​</a></h2><p>A conversation with a tool call and no result is invalid: providers reject it. A resumed conversation is no different, which means the session must record <strong>assistant messages with their tool calls</strong>, not only the results.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{&quot;role&quot;:&quot;assistant&quot;,&quot;toolCalls&quot;:[{&quot;id&quot;:&quot;call_1&quot;,&quot;name&quot;:&quot;read&quot;,&quot;arguments&quot;:&quot;...&quot;}]}</span></span>
<span class="line"><span>{&quot;role&quot;:&quot;tool&quot;,&quot;toolCallId&quot;:&quot;call_1&quot;,&quot;content&quot;:&quot;alpha&quot;}</span></span></code></pre></div><p>Record one and not the other, and the next run fails with a message about orphaned tool calls, three chapters after the bug was introduced.</p><h2 id="why-a-recorder-interface" tabindex="-1">Why a Recorder interface <a class="header-anchor" href="#why-a-recorder-interface" aria-label="Permalink to &quot;Why a Recorder interface&quot;">​</a></h2><p>The loop does not know where history lives. It is handed a history and returns a longer one. Sessions are a layer around the loop, which is why this chapter adds one file and edits <code>main</code>, and touches neither the loop nor the provider.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Knows about</th><th>Does not know about</th></tr></thead><tbody><tr><td>loop</td><td>messages, tools, providers</td><td>files, paths, formats</td></tr><tr><td>session</td><td>a file, append, load</td><td>the loop, the model, tools</td></tr><tr><td>main</td><td>flags, wiring</td><td>neither implementation detail</td></tr></tbody></table><h2 id="what-this-chapter-does-not-do" tabindex="-1">What this chapter does not do <a class="header-anchor" href="#what-this-chapter-does-not-do" aria-label="Permalink to &quot;What this chapter does not do&quot;">​</a></h2><ul><li>No branching. One file is one linear conversation.</li><li>No compaction. The file grows forever; chapter 07 starts deleting from the <em>request</em> while keeping the file intact.</li><li>No concurrency. Two processes appending to one session interleave, and nothing here prevents it.</li></ul><p>That last gap is worth naming rather than hiding. It is why pi locks its session files (<code>proper-lockfile</code> in its dependency list) and why this course defers it.</p><h2 id="where-the-real-implementations-go-further" tabindex="-1">Where the real implementations go further <a class="header-anchor" href="#where-the-real-implementations-go-further" aria-label="Permalink to &quot;Where the real implementations go further&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concern</th><th>pi</th><th>PiG</th></tr></thead><tbody><tr><td>Session shape</td><td>tree, every entry has a parent</td><td>ported tree</td></tr><tr><td>Branching and forking</td><td>copy a subtree into a new file</td><td>ported</td></tr><tr><td>Compaction</td><td>a summary entry replaces older messages <em>in the request</em></td><td>ported</td></tr><tr><td>Locking</td><td><code>proper-lockfile</code></td><td>ported</td></tr></tbody></table><p>The tree is what makes branching and compaction cheap. This chapter uses a line, which is the honest minimum and enough for eleven chapters.</p><h2 id="self-check" tabindex="-1">Self-check <a class="header-anchor" href="#self-check" aria-label="Permalink to &quot;Self-check&quot;">​</a></h2><ol><li>Why does an append-only log beat a snapshot after a crash? <em>(A session is a log, not a snapshot)</em></li><li>Name the two reasons the system message is not stored. <em>(Store the conversation. Rebuild the policy.)</em></li><li>What exactly does <code>len(prior)+1</code> skip? <em>(Resume is a slice, and the slice is where the bug is)</em></li><li>Which two records must both be written for a tool call, and what happens if one is missing? <em>(Tool pairs cross run boundaries too)</em></li><li>What does this chapter deliberately not handle? <em>(What this chapter does not do)</em></li></ol>`,25))])}const f=i(c,[["render",u]]);export{E as __pageData,f as default};
